INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('photo-gendler-hero', 'photo', 'gendler-hero', 'Leah and Naomi (hero photo)', '{"section":"home","caption":"Two young women in period coats smile warmly for the camera outdoors.","alt":"Two young women in period coats smile warmly for the camera outdoors."}', 0, 1, NULL, '/images/gendler-hero.jpg', '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-home-hero-intro', 'text_block', 'home-hero-intro', 'Sisters. Holocaust Survivors. Witnesses.', '{"section":"home","body":"The Gendler Girls is a tribute to the courage, love, and unbreakable bond between two sisters who survived the Holocaust together: Leah Gendler Fink and Naomi Gendler Jacobson.\n\nThrough firsthand testimony, archival images, and their enduring legacy, this site preserves not only their story, but the truth of what they lived through. It’s a space for remembrance, for education, and for bearing witness – so the world never forgets what hate made possible, and what love managed to endure.","variant":"hero-intro"}', 1, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
