INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-home-preserving', 'text_block', 'home-preserving-their-story', 'Preserving Their Story', '{"section":"home","body":"Leah and Naomi survived the Shoah together. Through years of persecution, displacement, starvation, and loss, the two sisters protected and encouraged one another under unimaginable circumstances.\n\nLeah, the older sister, was 19 years old when the Germans invaded in 1939 – tall, athletic, fearless, and fiercely protective of her younger sister. Naomi Jacobson, who was then called Hana, was only 11 years old, yet faced the horrors around her with remarkable maturity and resilience.\n\nTogether, they endured the destruction of their family, the brutality of the ghettos and camps, and the uncertainty of survival itself.","variant":"section-intro"}', 9, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-home-own-words', 'text_block', 'home-in-their-own-words', 'In Their Own Words', '{"section":"home","body":"In this documentary interview, Naomi Gendler Jacobson reflects on her memories of life in Lithuania before the war, the devastation brought by the Nazi invasion, and the years she endured during the Holocaust alongside her sister Leah.\n\nThrough firsthand testimony, she recounts survival, loss, resilience, and rebuilding a life after unimaginable tragedy. Her words preserve both historical truth and lived memory.","variant":"section-intro"}', 10, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('photo-chaya', 'photo', 'chaya', 'Two women in fur-collared coats', '{"section":"home","caption":"Two women in fur-collared coats smile together indoors, with onlookers visible behind them.","alt":"Two women in fur-collared coats smile together indoors, with onlookers visible behind them."}', 11, 1, NULL, '/images/chaya.jpg', '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-home-chaya', 'text_block', 'home-sister-who-did-not-survive', 'The Sister Who Did Not Survive', '{"section":"home","body":"Leah and Naomi were born to Joseph and Perel Gendler in Memel, Lithuania, alongside their older sister Chaya.\n\nBefore the war, they remembered living through what they later called the gu’te tzeiten – “the good times” – years of family, normalcy, and peace before the Nazi invasion shattered their world and forced them to flee for their lives.\n\nChaya did not survive the Holocaust. Neither did their parents, Chaya’s husband, their son Avram, nor many of their relatives. From their immediate family, only Leah and Naomi survived.","variant":"section-intro"}', 12, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-home-mission', 'text_block', 'home-our-mission', 'Our Mission', '{"section":"home","body":"Our main goal is to educate people about the Shoah, or the Holocaust, by shedding light on what life was really like in these incomprehensibly cruel circumstances. Sometimes it can be hard to imagine that these things actually did happen, so we feel that it is important to show the actual people who have lived through those experiences and managed to survive.In addition, we hope that sharing the video testimonies of Naomi and Leah Gendler, and photos and details of life as it progressed in the years and decades after the war, will not only provide an inspirational view of their spirit to survive and build new lives, but also will provide an unassailable answer to those misguided individuals who already in our time are beginning to doubt if these events actually occurred.It is our sincerest wish that by sharing Naomi and Leah’s incredible and inspirational stories, we can honor the memories of the 29,000 souls that were lost in the Kovno ghetto, the 65,000 souls that were lost in the Stutthoff concentration camp, and the 10,000 souls lost at the 7th Fort.\n\nBy sharing these intimate stories, it is our hope that their experiences are never forgotten and more importantly, never repeated.","variant":"section-intro"}', 13, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('text-their-story-intro', 'text_block', 'their-story-in-their-words', 'In Their Words', '{"section":"their-story","body":"Firsthand testimony from Leah and Naomi Gendler. Their voices carry the weight of memory and the strength of survival. These are their stories.","variant":"section-intro"}', 0, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('video-naomi-story', 'video', 'naomi-story', 'A Personal Interview with Mrs. Naomi Jacobson - Documentary - Memories from Lithuania', '{"section":"their-story","youtube_id":"RYo37fxAh1I","description":"In this documentary interview, Naomi Gendler Jacobson reflects on her memories of life in Lithuania before the war, the devastation brought by the Nazi invasion, and the years she endured during the Holocaust alongside her sister Leah.\n\nThrough firsthand testimony, she recounts survival, loss, resilience, and rebuilding a life after unimaginable tragedy. Her words preserve both historical truth and lived memory."}', 1, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
