INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('photo-chattanooga', 'photo', 'chattanooga', 'Chattanooga News front page, March 23, 1939', '{"section":"references","caption":"The front page of the Chattanooga News March 23, 1939 features the headline of Hitler''s speech in Memel.","alt":"Front page of the Chattanooga News, March 23, 1939."}', 2, 1, NULL, '/images/chattanooga.jpg', '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('photo-wix-img-20180408', 'photo', 'wix-img-20180408', 'Chattanooga News front page, March 23, 1939 (Wix original)', '{"section":"references","caption":"The front page of the Chattanooga News, March 23, 1939.","alt":"Photograph of the front page of The Chattanooga News, March 23, 1939, with the headline about Hitler in Memel."}', 3, 1, NULL, '/images/wix-IMG_20180408.jpg', '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);
INSERT OR IGNORE INTO entities (id, type, slug, title, data, position, visible, album, image_key, created_at, updated_at, deleted_at) VALUES ('story-irwin-jacobson', 'story', 'irwin-jacobson', 'Irwin Jacobson', '{"section":"family","body":"Irwin Jacobson of blessed memory was born in 1924 in Chicago. His father Abraham was born in _______________ and his mother Esther was born in  ___________________. He grew up speaking only Yiddish at home until he went off to kindergarten. (Actually he recalled coming  home the first day and not going back until first grade!). Therefore, culturally and coupled with  his innate sensitivity, he was destined to be a perfect match for Naomi.    \n\nAs cousin Rabbi Yehuda Silver observed in the attached reel, ”As a US veteran serving during World War Two , there was a sense he participated in what was going on- that he was one of them. His strength of character, his personality, kind and smooth, easy to be with. It wasn’t just Naomi. It was Naomi and Irwin.”   \n\nHe recalled going to synagogue with his father, and studied at the Hebrew Theological college while in high school\n\nIrwin was a talented clarinetist, and was selected as the Concert Meister of the very large band at Manley hgh school. He was beloved by his friends, and as one friend wrote in Irwin’s yearbook, he was a “swell guy” and that was how was perceived throughout his life.\n\nWhen World War two beckoned and he was drafted, his great musical talent .. served on Air Force band until sent overseas to India. He loved America.\n\nHe like to read, follow the news, was a member of book clubs.  \n\nHe was a role model to his two daughters and his soon he was so proud of, fond of and loved by nephews and nieces. Sunday trips to museums, barbeques at the forest preserve, fireworks on July 4th, concerts at Grant Park","draft":true}', 0, 1, NULL, NULL, '2026-11-12T00:00:00Z', '2026-11-12T00:00:00Z', NULL);

